// Construir body para Gemini generateContent con el PDF subido y prompt de corrección.
// FIX (auditoría completa de la rúbrica): ahora se envía la rúbrica COMPLETA al modelo —
//   * criterio.instrucciones_puntuacion (topes/reglas)   [antes NO se enviaba]
//   * subcriterio.evidencias (checklist verificable)      [antes NO se enviaba]
//   * rubrica.metadata (contexto adicional)               [antes NO se enviaba]
// Penalizaciones y condiciones ya se enviaban y se mantienen.
// El contrato de SALIDA (responseSchema basado en `nombre`) NO cambia.

const uploadResponse = $input.first().json;
const apiKey = $('Decodificar PDF1').first().json.api_key;
const rubrica = $('Decodificar PDF1').first().json.rubrica;
const contexto = $('Decodificar PDF1').first().json.contexto;

if (uploadResponse.error) {
  throw new Error(`Error al subir PDF a Gemini: ${JSON.stringify(uploadResponse.error)}`);
}

const fileUri = uploadResponse.file?.uri;
if (!fileUri) {
  throw new Error('No se obtuvo URI del archivo subido a Gemini');
}

// --- Criterios CON instrucciones_puntuacion + subcriterios + evidencias ---
let criteriosTexto = '';
for (const criterio of (rubrica.criterios || [])) {
  const puntajeMax = criterio.puntaje_maximo || criterio.peso || 0;
  const cid = criterio.id ? `[${criterio.id}] ` : '';
  criteriosTexto += `- ${cid}${criterio.nombre} (${puntajeMax} pts): ${criterio.descripcion || ''}\n`;
  if (criterio.instrucciones_puntuacion) {
    criteriosTexto += `  Instrucciones de puntuación (TOPES/REGLAS OBLIGATORIAS): ${criterio.instrucciones_puntuacion}\n`;
  }
  if (criterio.subcriterios && criterio.subcriterios.length > 0) {
    for (const sub of criterio.subcriterios) {
      criteriosTexto += `  * ${sub.descripcion || ''}\n`;
      if (sub.evidencias && sub.evidencias.length > 0) {
        for (const ev of sub.evidencias) {
          criteriosTexto += `    - [ ] ${ev}\n`;
        }
      }
    }
  }
}

// --- Metadata / contexto adicional de la rúbrica ---
let metadataTexto = '';
if (rubrica.metadata && Object.keys(rubrica.metadata).length > 0) {
  metadataTexto = '\n## CONTEXTO ADICIONAL DE LA RÚBRICA\n';
  for (const clave of Object.keys(rubrica.metadata)) {
    metadataTexto += `- ${clave}: ${rubrica.metadata[clave]}\n`;
  }
}

// --- Penalizaciones (se mantienen) ---
let penalizacionesTexto = '';
if (rubrica.penalizaciones && rubrica.penalizaciones.length > 0) {
  penalizacionesTexto = '\n## PENALIZACIONES\n';
  for (const p of rubrica.penalizaciones) {
    penalizacionesTexto += `- ${p.descripcion}: descuento de ${p.descuento_porcentaje}% a aplicar reduciendo el puntaje_obtenido del criterio afectado (NO como descuento global sobre la nota).\n`;
  }
}

// --- Condiciones de desaprobación (se mantienen) ---
let condicionesTexto = '';
if (rubrica.condiciones_desaprobacion && rubrica.condiciones_desaprobacion.length > 0) {
  condicionesTexto = '\n## CONDICIONES DE DESAPROBACIÓN AUTOMÁTICA\n';
  for (const c of rubrica.condiciones_desaprobacion) {
    const techo = c.nota_maxima || c.nota_final || 0;
    condicionesTexto += `- Si: ${c.condicion} → la nota máxima permitida es ${techo}. La nota final será min(suma_criterios, ${techo}).\n`;
  }
}

const prompt = `Eres un evaluador académico experto en la materia "${contexto?.materia || 'sin especificar'}".

Tu tarea es evaluar la entrega del alumno "${contexto?.alumno || 'sin especificar'}" a partir del PDF adjunto, según la rúbrica proporcionada.

El PDF puede contener informes, documentos, diagramas, capturas de pantalla, fragmentos de código, tablas o ejercicios resueltos a mano. Lee e interpreta TODO el contenido del PDF con atención, incluyendo las IMÁGENES y DIAGRAMAS, no solo el texto.

## RÚBRICA DE EVALUACIÓN

Título: ${rubrica.titulo || 'Sin título'}
Descripción: ${rubrica.descripcion || ''}
Tipo: ${rubrica.tipo || 'TP'}
Puntaje máximo: ${rubrica.puntaje_maximo || 100}
${metadataTexto}
Criterios a evaluar. Cada criterio incluye su descripción, sus instrucciones de puntuación (cuando existen) y, debajo de cada subcriterio, las EVIDENCIAS verificables que debés chequear una por una en el PDF:

${criteriosTexto}${penalizacionesTexto}${condicionesTexto}

## INSTRUCCIONES DE EVALUACIÓN

Para cada criterio de la rúbrica:
1. Verificá UNA POR UNA las evidencias listadas del criterio contra el contenido real del PDF. Una evidencia solo cuenta como cumplida si está REALMENTE presente en la entrega. La mención o descripción que el alumno hace de algo (por ejemplo, de su propio código) NO es evidencia de que ese algo exista o sea correcto.
2. Respetá de forma OBLIGATORIA las "Instrucciones de puntuación" del criterio: los topes (por ejemplo, "máximo 55% si no se entrega el código") son límites estrictos, no sugerencias. Si se cumple la condición de un tope, el puntaje del criterio NO puede superarlo, por más que otras evidencias estén bien.
3. Asigná un puntaje entre 0 y el máximo del criterio, coherente con las evidencias cumplidas y con los topes aplicables.
4. Determiná el estado:
   - "OK" si logra ≥80% del puntaje máximo del criterio
   - "WARNING" si logra 40-79% del puntaje máximo
   - "ERROR" si logra <40% del puntaje máximo
5. Proporcioná feedback específico citando las evidencias cumplidas y las faltantes que observaste (o no) en el PDF.

Además:
- Listá 2-4 fortalezas de la entrega (array de strings)
- Listá 2-4 recomendaciones de mejora específicas (array de strings)
- Escribí un comentario general de 2-3 oraciones sobre la calidad global del trabajo

## FORMATO DE RESPUESTA OBLIGATORIO

Respondé ÚNICAMENTE con un JSON válido con esta estructura exacta:

{
  "nota": <suma exacta de todos los puntaje_obtenido>,
  "criterios": [
    {
      "nombre": "<nombre exacto del criterio de la rúbrica>",
      "puntaje_obtenido": <número>,
      "puntaje_maximo": <número>,
      "estado": "<OK|WARNING|ERROR>",
      "feedback": "<feedback específico basado en lo observado en el PDF>"
    }
  ],
  "fortalezas": ["<fortaleza 1>", "<fortaleza 2>"],
  "recomendaciones": ["<recomendación 1>", "<recomendación 2>"],
  "comentario_general": "<comentario de 2-3 oraciones>"
}

IMPORTANTE:
- La nota SIEMPRE es la suma exacta de puntaje_obtenido de todos los criterios (las penalizaciones ya están aplicadas dentro de cada criterio, nunca como descuento posterior).
- Cada criterio de la rúbrica debe aparecer en la respuesta, con su nombre EXACTO.
- El estado debe calcularse según el porcentaje del criterio individual.
- NO incluyas texto antes o después del JSON.
- NO uses markdown code blocks, solo JSON puro.`;

// Construir body para Gemini API con el PDF referenciado por URI
const body = {
  generationConfig: {
    temperature: 0.2,
    topK: 40,
    topP: 0.95,
    candidateCount: 1,
    responseMimeType: "application/json",
    responseSchema: {
      type: "object",
      properties: {
        nota: { type: "number" },
        criterios: {
          type: "array",
          items: {
            type: "object",
            properties: {
              nombre: { type: "string" },
              puntaje_obtenido: { type: "number" },
              puntaje_maximo: { type: "number" },
              estado: { type: "string", enum: ["OK", "WARNING", "ERROR"] },
              feedback: { type: "string" }
            },
            required: ["nombre", "puntaje_obtenido", "puntaje_maximo", "estado", "feedback"]
          }
        },
        fortalezas: { type: "array", items: { type: "string" } },
        recomendaciones: { type: "array", items: { type: "string" } },
        comentario_general: { type: "string" }
      },
      required: ["nota", "criterios", "fortalezas", "recomendaciones", "comentario_general"]
    }
  },
  contents: [
    {
      role: "user",
      parts: [
        { fileData: { fileUri: fileUri, mimeType: "application/pdf" } },
        { text: prompt }
      ]
    }
  ]
};

return [{ json: { geminiBody: body, api_key: apiKey } }];

// Decodificar el PDF recibido en base64 a binario para subirlo a Gemini Files API.
// Pasa adelante api_key, rubrica y contexto para que los nodos posteriores los lean
// vía $('Decodificar PDF1').

const datos = $input.first().json;
const pdfBase64 = datos.pdf_base64;

if (!pdfBase64) {
  throw new Error('No se recibió pdf_base64 en el request');
}

// Limpiar prefijo data URI si viene (ej: "data:application/pdf;base64,....")
const cleanBase64 = pdfBase64.includes(',') ? pdfBase64.split(',').pop() : pdfBase64;

const buffer = Buffer.from(cleanBase64, 'base64');

// prepareBinaryData arma el item binario que espera el nodo HTTP de upload
const binaryData = await this.helpers.prepareBinaryData(
  buffer,
  'entrega.pdf',
  'application/pdf'
);

return [
  {
    json: {
      api_key: datos.api_key,
      rubrica: datos.rubrica,
      contexto: datos.contexto,
    },
    binary: {
      pdf: binaryData,
    },
  },
];

// Parser de respuesta de Gemini para corrección PDF
// Mismo patrón que correccion-workflow.json

const geminiResponse = $input.first().json;
const startTime = Date.now();

try {
  // Verificar si hay error de Gemini (503, 429, 500, etc.)
  if (geminiResponse.error) {
    const errorMsg = geminiResponse.error.message || JSON.stringify(geminiResponse.error);
    const errorCode = geminiResponse.error.code || 'UNKNOWN';

    return [{
      json: {
        success: false,
        error: {
          code: 'GEMINI_ERROR',
          message: `Error de Gemini [${errorCode}]: ${errorMsg}`,
          retry: errorCode === 503 || errorCode === 500
        }
      }
    }];
  }

  // Normalizar respuesta (puede venir como array o objeto)
  let responseArray;
  if (Array.isArray(geminiResponse)) {
    responseArray = geminiResponse;
  } else if (geminiResponse.body && Array.isArray(geminiResponse.body)) {
    responseArray = geminiResponse.body;
  } else if (geminiResponse.data && Array.isArray(geminiResponse.data)) {
    responseArray = geminiResponse.data;
  } else {
    responseArray = [geminiResponse];
  }

  const candidate = responseArray[0]?.candidates?.[0];

  if (!candidate) {
    return [{
      json: {
        success: false,
        error: {
          code: 'PARSING_ERROR',
          message: 'No se encontró candidate en respuesta de Gemini',
          retry: true
        }
      }
    }];
  }

  const textContent = candidate.content?.parts?.[0]?.text;

  if (!textContent) {
    return [{
      json: {
        success: false,
        error: {
          code: 'PARSING_ERROR',
          message: 'No se encontró texto en la respuesta',
          retry: true
        }
      }
    }];
  }

  // Parsear el JSON (responseMimeType: application/json garantiza JSON puro)
  const parsedData = JSON.parse(textContent);

  // Validar estructura mínima
  if (!parsedData.nota && parsedData.nota !== 0) {
    return [{
      json: {
        success: false,
        error: {
          code: 'PARSING_ERROR',
          message: "Respuesta no contiene campo 'nota'",
          retry: true
        }
      }
    }];
  }

  if (!Array.isArray(parsedData.criterios)) {
    return [{
      json: {
        success: false,
        error: {
          code: 'PARSING_ERROR',
          message: "Respuesta no contiene 'criterios' como array",
          retry: true
        }
      }
    }];
  }

  // Construir metadata
  const elapsedTime = Date.now() - startTime;
  const metadata = {
    modelo: 'gemini-2.5-flash',
    modo: 'vision-pdf',
    tokens_entrada: candidate.tokenCount?.totalTokens || 0,
    tokens_salida: candidate.tokenCount?.candidatesTokenCount || 0,
    tiempo_ms: elapsedTime
  };

  // Retornar resultado exitoso — mismo contrato que correccion-workflow.json
  return [{
    json: {
      success: true,
      correccion: {
        nota: parsedData.nota,
        criterios: parsedData.criterios,
        fortalezas: parsedData.fortalezas || [],
        recomendaciones: parsedData.recomendaciones || [],
        comentario_general: parsedData.comentario_general || ''
      },
      metadata: metadata
    }
  }];

} catch (error) {
  return [{
    json: {
      success: false,
      error: {
        code: 'PARSING_ERROR',
        message: `Error al procesar corrección PDF: ${error.message}`,
        retry: true
      }
    }
  }];
}
